import{_ as t,o,c as i,a2 as n}from"./chunks/framework.BXzK3EA4.js";const r="/assets/one.UEBlffHO.png",a="/assets/two.DqIYHUkf.png",s="/assets/three.CgrNC68L.png",_=JSON.parse('{"title":"Definedge","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/definedge.md","filePath":"connect-brokers/brokers/definedge.md"}'),c={name:"connect-brokers/brokers/definedge.md"};function d(l,e,g,p,u,h){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="definedge" tabindex="-1">Definedge <a class="header-anchor" href="#definedge" aria-label="Permalink to &quot;Definedge&quot;">​</a></h1><p>Tradeboard provides seamless integration with Definedge Securities, enabling you to connect your trading strategies with Definedge’s brokerage services. Follow this guide to set up your Definedge broker account with Tradeboard.</p><p><strong>Prerequisites</strong></p><p>Before proceeding, ensure you have the following:</p><ul><li>An active Definedge Securities trading account.</li><li>Access to <a href="https://myaccount.definedgesecurities.com/" target="_blank" rel="noreferrer">Definedge Securities Portal</a>.</li><li>Tradeboard installed and configured on your local machine.</li></ul><h3 id="steps-to-create-the-definedge-api-secret-key" tabindex="-1">Steps to Create the Definedge API Secret Key <a class="header-anchor" href="#steps-to-create-the-definedge-api-secret-key" aria-label="Permalink to &quot;Steps to Create the Definedge API Secret Key&quot;">​</a></h3><h4 id="_1-login-to-definedge-securities-portal" tabindex="-1">1. Login to Definedge Securities Portal <a class="header-anchor" href="#_1-login-to-definedge-securities-portal" aria-label="Permalink to &quot;1. Login to Definedge Securities Portal&quot;">​</a></h4><ul><li>Navigate to <a href="https://myaccount.definedgesecurities.com/" target="_blank" rel="noreferrer">https://myaccount.definedgesecurities.com/</a>.</li><li>Enter your <strong>UCC (Account ID)</strong> and <strong>password</strong>.</li></ul><figure><img src="'+r+'" alt=""><figcaption></figcaption></figure><ul><li>Complete with OTP authentication send to your registered mobile and email ID.</li></ul><figure><img src="'+a+'" alt=""><figcaption></figcaption></figure><ul><li>This will take you to your dashboard.</li></ul><h4 id="_2-access-api-key-section" tabindex="-1">2. Access API Key Section <a class="header-anchor" href="#_2-access-api-key-section" aria-label="Permalink to &quot;2. Access API Key Section&quot;">​</a></h4><ul><li>From the dashboard, go to the <strong>Account</strong> section.</li><li>Click on <strong>Show my API Secret</strong>.</li><li>Here you will find your <strong>API Token</strong> and <strong>API Secret</strong>.</li></ul><figure><img src="'+s+`" alt=""><figcaption></figcaption></figure><p><strong>Configuring the .env File</strong></p><p>The Definedge API Token is used as the API key and API Secrets as API Secret itself. Below is a sample configuration for the .env file</p><p>#Definedge Broker Configuration</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Definedge Broker Configuration</span></span>
<span class="line"><span>BROKER_API_KEY = &#39;your_API_Token_here&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_API_Secret_here&#39; </span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/definedge/callback&#39;</span></span></code></pre></div><p><strong>Important Notes</strong></p><ul><li>Ensure that your <strong>API Secret Key and API Token</strong> are stored securely and is not shared publicly.</li><li>The <strong>REDIRECT_URL</strong> should match the one registered with your API application.</li></ul><p>Follow these steps to integrate Definedge with Tradeboard successfully. If you encounter any issues, refer to the Definedge API documentation for further assistance.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/definedge/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,25)])])}const m=t(c,[["render",d]]);export{_ as __pageData,m as default};
